1\";i:17;s:6:\"image2\";i:18;s:6:\"image3\";i:19;s:6:\"image4\";i:20;s:7:\"user_id\";i:21;s:11:\"is_verified\";}s:10:\"\0*\0guarded\";a:1:{i:0;s:1:\"*\";}}i:5;O:15:\"App\\Models\\Post\":33:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:5:\"posts\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:26:{s:2:\"id\";i:5238;s:7:\"article\";s:181:\"বিশ্বকাপ ক্রিকেট ২০২৩-এ বাংলাদেশের কোন খেলোয়াড় সর্বোচ্চ রান করেন?\";s:1:\"a\";s:22:\"লিটন দাস\";s:1:\"b\";s:37:\"মুশফিকুর রহিম\";s:1:\"c\";s:38:\"সাকিব আল হাসান\";s:1:\"d\";s:55:\"মাহমুদুল্লাহ রিয়াদ\";s:3:\"ans\";s:3:\"ঘ\";s:11:\"explanation\";s:1280:\"২০২৩ সালের আইসিসি বিশ্বকাপে বাংলাদেশের পক্ষে অভিজ্ঞ ব্যাটার মাহমুদুল্লাহ রিয়াদ ৮ ইনিংসে ৩২৮ রান করে দলের সর্বোচ্চ রান সংগ্রাহক হন।\n\nলিটন দাস এবং মুশফিকুর রহিম কিছু ভালো ইনিংস খেললেও তাদের মোট রান মাহমুদুল্লাহর থেকে কম ছিল।\nসাকিব আল হাসান ইনজুরি ও ফর্মের কারণে এই আসরে প্রত্যাশিত রান সংগ্রহ করতে পারেননি।\nমাহমুদুল্লাহ রিয়াদ দক্ষিণ আফ্রিকার বিপক্ষে এই আসরে বাংলাদেশের একমাত্র সেঞ্চুরিটি হাঁকান।\n\nঅতিরিক্ত তথ্য: এই বিশ্বকাপে বাংলাদেশের অবস্থান ছিল পয়েন্ট টেবিলের অষ্টম স্থানে।\";s:9:\"answer_id\";N;s:10:\"subject_id\";i:81;s:7:\"chapter\";N;s:10:\"topic_name\";s:6:\"Sports\";s:8:\"category\";s:3:\"MCQ\";s:8:\"board_id\";N;s:4:\"year\";s:2:\"46\";s:5:\"class\";N;s:14:\"institution_id\";i:4;s:6:\"image1\";N;s:6:\"image2\";N;s:6:\"image3\";N;s:6:\"image4\";N;s:7:\"user_id\";N;s:11:\"is_verified\";i:0;s:10:\"created_at\";s:19:\"2026-01-29 23:15:16\";s:10:\"updated_at\";s:19:\"2026-01-29 23:15:16\";s:10:\"was_viewed\";i:0;}s:11:\"\0*\0original\";a:26:{s:2:\"id\";i:5238;s:7:\"article\";s:181:\"বিশ্বকাপ ক্রিকেট ২০২৩-এ বাংলাদেশের কোন খেলোয়াড় সর্বোচ্চ রান করেন?\";s:1:\"a\";s:22:\"লিটন দাস\";s:1:\"b\";s:37:\"মুশফিকুর রহিম\";s:1:\"c\";s:38:\"সাকিব আল হাসান\";s:1:\"d\";s:55:\"মাহমুদুল্লাহ রিয়াদ\";s:3:\"ans\";s:3:\"ঘ\";s:11:\"explanation\";s:1280:\"২০২৩ সালের আইসিসি বিশ্বকাপে বাংলাদেশের পক্ষে অভিজ্ঞ ব্যাটার মাহমুদুল্লাহ রিয়াদ ৮ ইনিংসে ৩২৮ রান করে দলের সর্বোচ্চ রান সংগ্রাহক হন।\n\nলিটন দাস এবং মুশফিকুর রহিম কিছু ভালো ইনিংস খেললেও তাদের মোট রান মাহমুদুল্লাহর থেকে কম ছিল।\nসাকিব আল হাসান ইনজুরি ও ফর্মের কারণে এই আসরে প্রত্যাশিত রান সংগ্রহ করতে পারেননি।\nমাহমুদুল্লাহ রিয়াদ দক্ষিণ আফ্রিকার বিপক্ষে এই আসরে বাংলাদেশের একমাত্র সেঞ্চুরিটি হাঁকান।\n\nঅতিরিক্ত তথ্য: এই বিশ্বকাপে বাংলাদেশের অবস্থান ছিল পয়েন্ট টেবিলের অষ্টম স্থানে।\";s:9:\"answer_id\";N;s:10:\"subject_id\";i:81;s:7:\"chapter\";N;s:10:\"topic_name\";s:6:\"Sports\";s:8:\"category\";s:3:\"MCQ\";s:8:\"board_id\";N;s:4:\"year\";s:2:\"46\";s:5:\"class\";N;s:14:\"institution_id\";i:4;s:6:\"image1\";N;s:6:\"image2\";N;s:6:\"image3\";N;s:6:\"image4\";N;s:7:\"user_id\";N;s:11:\"is_verified\";i:0;s:10:\"created_at\";s:19:\"2026-01-29 23:15:16\";s:10:\"updated_at\";s:19:\"2026-01-29 23:15:16\";s:10:\"was_viewed\";i:0;}s:10:\"\0*\0changes\";a:0:{}s:11:\"\0*\0previous\";a:0:{}s:8:\"\0*\0casts\";a:2:{s:4:\"year\";s:7:\"integer\";s:5:\"class\";s:6:\"string\";}s:17:\"\0*\0classCastCache\";a:0:{}s:21:\"\0*\0attributeCastCache\";a:0:{}s:13:\"\0*\0dateFormat\";N;s:10:\"\0*\0appends\";a:0:{}s:19:\"\0*\0dispatchesEvents\";a:0:{}s:14:\"\0*\0observables\";a:0:{}s:12:\"\0*\0relations\";a:3:{s:11:\"institution\";r:83;s:7:\"subject\";O:18:\"App\\Models\\Subject\":33:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:8:\"subjects\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:9:{s:2:\"id\";i:81;s:4:\"name\";s:18:\"Bangladesh affairs\";s