:8:\"board_id\";i:13;s:4:\"year\";i:14;s:5:\"class\";i:15;s:14:\"institution_id\";i:16;s:6:\"image1\";i:17;s:6:\"image2\";i:18;s:6:\"image3\";i:19;s:6:\"image4\";i:20;s:7:\"user_id\";i:21;s:11:\"is_verified\";}s:10:\"\0*\0guarded\";a:1:{i:0;s:1:\"*\";}}i:12;O:15:\"App\\Models\\Post\":33:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:5:\"posts\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:26:{s:2:\"id\";i:5245;s:7:\"article\";s:134:\"‘মুজিব: একটি জাতির রূপকার’ চলচ্চিত্রের পরিচালক কে?\";s:1:\"a\";s:25:\"গুরু দত্ত\";s:1:\"b\";s:28:\"শিবু সিরিল\";s:1:\"c\";s:37:\"শ্যাম বেনেগাল\";s:1:\"d\";s:37:\"বিশাল ভরদ্বাজ\";s:3:\"ans\";s:3:\"গ\";s:11:\"explanation\";s:1359:\"বঙ্গবন্ধু শেখ মুজিবুর রহমানের জীবনীভিত্তিক ‘মুজিব: দ্য মেকিং অফ আ নেশন’ চলচ্চিত্রটি প্রখ্যাত ভারতীয় পরিচালক শ্যাম বেনেগাল পরিচালনা করেছেন।\n\nগুরু দত্ত ছিলেন একজন কিংবদন্তি ভারতীয় অভিনেতা ও পরিচালক যিনি অনেক আগে প্রয়াত হয়েছেন।\nবিশাল ভরদ্বাজ একজন আধুনিক নির্মাতা হলেও এই চলচ্চিত্রের পরিচালনার সাথে তিনি যুক্ত ছিলেন না।\nশ্যাম বেনেগাল তাঁর রাজনৈতিক এবং ঐতিহাসিক বায়োপিক তৈরির দক্ষতার জন্য বিশ্বব্যাপী সমাদৃত।\n\nঅতিরিক্ত তথ্য: এটি বাংলাদেশ ও ভারতের যৌথ প্রযোজনায় নির্মিত একটি অত্যন্ত ব্যয়বহুল চলচ্চিত্র।\";s:9:\"answer_id\";N;s:10:\"subject_id\";i:81;s:7:\"chapter\";N;s:10:\"topic_name\";s:18:\"Bangladesh Affairs\";s:8:\"category\";s:3:\"MCQ\";s:8:\"board_id\";N;s:4:\"year\";s:2:\"46\";s:5:\"class\";N;s:14:\"institution_id\";i:4;s:6:\"image1\";N;s:6:\"image2\";N;s:6:\"image3\";N;s:6:\"image4\";N;s:7:\"user_id\";N;s:11:\"is_verified\";i:0;s:10:\"created_at\";s:19:\"2026-01-29 23:15:16\";s:10:\"updated_at\";s:19:\"2026-01-29 23:15:16\";s:10:\"was_viewed\";i:0;}s:11:\"\0*\0original\";a:26:{s:2:\"id\";i:5245;s:7:\"artic