ation\";i:7;s:9:\"answer_id\";i:8;s:10:\"subject_id\";i:9;s:7:\"chapter\";i:10;s:10:\"topic_name\";i:11;s:8:\"category\";i:12;s:8:\"board_id\";i:13;s:4:\"year\";i:14;s:5:\"class\";i:15;s:14:\"institution_id\";i:16;s:6:\"image1\";i:17;s:6:\"image2\";i:18;s:6:\"image3\";i:19;s:6:\"image4\";i:20;s:7:\"user_id\";i:21;s:11:\"is_verified\";}s:10:\"\0*\0guarded\";a:1:{i:0;s:1:\"*\";}}i:13;O:15:\"App\\Models\\Post\":33:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:5:\"posts\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:26:{s:2:\"id\";i:5246;s:7:\"article\";s:248:\"বঙ্গবন্ধু শেখ মুজিবুর রহমান জাতিসংঘের সাধারণ পরিষদে ১৯৭৪ সালের কোন মাসে বাংলায় বক্তৃতা দেন?\";s:1:\"a\";s:30:\"সেপ্টেম্বর\";s:1:\"b\";s:21:\"অক্টোবর\";s:1:\"c\";s:21:\"নভেম্বর\";s:1:\"d\";s:24:\"ডিসেম্বর\";s:3:\"ans\";s:3:\"ক\";s:11:\"explanation\";s:1266:\"১৯৭৪ সালের ২৫শে সেপ্টেম্বর জাতিসংঘ সাধারণ পরিষদের ২৯তম অধিবেশনে বঙ্গবন্ধু প্রথম রাষ্ট্রনায়ক হিসেবে বাংলায় ভাষণ দেন।\n\nঅক্টোবর মাসে বাংলাদেশ জাতিসংঘে তাঁর সদস্যপদের কার্যকর কার্যক্রম অনেক ক্ষেত্রে এগিয়ে নিয়েছিল।\nনভেম্বর বা ডিসেম্বর মাসে ঐতিহাসিক এই বক্তৃতার কোনো নজির আন্তর্জাতিক দলিলে নেই।\nএই বক্তৃতার মাধ্যমে বঙ্গবন্ধু বিশ্বমঞ্চে বাংলা ভাষাকে এক অনন্য উচ্চতায় নিয়ে গিয়েছিলেন।\n\nঅতিরিক্ত তথ্য: বাংলাদেশ ১৯৭৪ সালের ১৭ই সেপ্টেম্বর জাতিসংঘের ১৩৬তম সদস্যপদ লাভ করে।\";s:9:\"answer_id\";N;s:10:\"subject_id\";i:81;s:7:\"chapter\";N;s:10:\"topic_name\";s:7:\"History\";s:8:\"category\";s:3:\"MCQ\";s:8:\"board_id\";N;s:4:\"year\";s:2:\"46\";s:5:\"class\";N;s:14:\"institution_id\";i:4;s:6:\"image1\";N;s:6:\"image2\";N;s:6:\"image3\";N;s:6:\"image4\";N;s:7:\"user_id\";N;s:11:\"is_verified\";i:0;s:10:\"created_at\";s:19:\"2026-01-29 23:15:16\";s:10:\"updated_at\";s:19: