3;s:7:\"subject\";r:755;s:5:\"board\";N;}s:10:\"\0*\0touches\";a:0:{}s:27:\"\0*\0relationAutoloadCallback\";N;s:26:\"\0*\0relationAutoloadContext\";N;s:10:\"timestamps\";b:1;s:13:\"usesUniqueIds\";b:0;s:9:\"\0*\0hidden\";a:0:{}s:10:\"\0*\0visible\";a:0:{}s:11:\"\0*\0fillable\";a:22:{i:0;s:7:\"article\";i:1;s:1:\"a\";i:2;s:1:\"b\";i:3;s:1:\"c\";i:4;s:1:\"d\";i:5;s:3:\"ans\";i:6;s:11:\"explanation\";i:7;s:9:\"answer_id\";i:8;s:10:\"subject_id\";i:9;s:7:\"chapter\";i:10;s:10:\"topic_name\";i:11;s:8:\"category\";i:12;s:8:\"board_id\";i:13;s:4:\"year\";i:14;s:5:\"class\";i:15;s:14:\"institution_id\";i:16;s:6:\"image1\";i:17;s:6:\"image2\";i:18;s:6:\"image3\";i:19;s:6:\"image4\";i:20;s:7:\"user_id\";i:21;s:11:\"is_verified\";}s:10:\"\0*\0guarded\";a:1:{i:0;s:1:\"*\";}}i:16;O:15:\"App\\Models\\Post\":33:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:5:\"posts\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:26:{s:2:\"id\";i:5249;s:7:\"article\";s:166:\"দ্বাদশ জাতীয় সংসদ নির্বাচনে ভোটার উপস্থিতির হার কত শতাংশ ছিল?\";s:1:\"a\";s:10:\"৪০.৮\";s:1:\"b\";s:10:\"৪০.৯\";s:1:\"c\";s:10:\"৪১.৬\";s:1:\"d\";s:10:\"৪১.৮\";s:3:\"ans\";s:3:\"ঘ\";s:11:\"explanation\";s:1195:\"২০২৪ সালের ৭ই জানুয়ারি অনুষ্ঠিত দ্বাদশ জাতীয় সংসদ নির্বাচনে নির্বাচন কমিশনের তথ্যমতে মোট ৪১.৮% ভোট পড়েছে।\n\n৪০.৮ বা ৪০.৯ শতাংশ ছিল ভোট গ্রহণ চলাকালীন সময়ের প্রাথমিক ধারণা যা চূড়ান্ত হিসাবে সামান্য বেড়েছে।\n৪১.৬ শতাংশ ভোটার উপস্থিতির তথ্যটি সঠিক নয় কারণ চূড়ান্ত সরকারি গেজেটে হারটি ৪১.৮ ছিল।\nএই নির্বাচনে ২৮টি রাজনৈতিক দল অংশ নিলেও প্রধান বিরোধী দল বিএনপি এটি বর্জন করেছিল।\n\nঅতিরিক্ত তথ্য: ৩০০টি আসনের মধ্যে ২৯৯টি আসনে ভোট গ্রহণ অনুষ্ঠিত হয়েছিল।\";s:9:\"answer_id\";N;s:10:\"subject_id\";i:81;s:7:\"chapter\";N;s:10: