:1:{i:0;s:1:\"*\";}}i:7;O:15:\"App\\Models\\Post\":33:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:5:\"posts\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:26:{s:2:\"id\";i:5240;s:7:\"article\";s:139:\"কৃষ্ণগহ্বর নিয়ে কোন বাঙালি বিজ্ঞানী গবেষণা করেছেন?\";s:1:\"a\";s:32:\"কুদরত-ই-খুদা\";s:1:\"b\";s:50:\"কাজী মোতাহার হোসেন\";s:1:\"c\";s:47:\"জামাল নজরুল ইসলাম\";s:1:\"d\";s:50:\"আব্দুল মতিন চৌধুরী\";s:3:\"ans\";s:3:\"গ\";s:11:\"explanation\";s:1347:\"জামাল নজরুল ইসলাম ছিলেন একজন বিশ্বখ্যাত মহাকাশ বিজ্ঞানী যিনি কৃষ্ণগহ্বর বা ব্ল্যাকহোল এবং মহাবিশ্বের চূড়ান্ত পরিণতি নিয়ে গবেষণা করেছেন।\n\nড. কুদরত-ই-খুদা মূলত রসায়নবিদ ছিলেন যিনি পাট থেকে আঁশ ও জ্বালানি তৈরির গবেষণায় অবদান রাখেন।\nকাজী মোতাহার হোসেন একজন পরিসংখ্যানবিদ ও সাহিত্যিক হিসেবে বেশি পরিচিত ছিলেন।\nআব্দুল মতিন চৌধুরী ছিলেন একজন প্রখ্যাত পদার্থবিদ কিন্তু কৃষ্ণগহ্বর তাঁর প্রধান গবেষণার ক্ষেত্র ছিল না।\n\n\n\nঅতিরিক্ত তথ্য: তাঁর বিখ্যাত গ্রন্থ ‘The Ultimate Fate of the Universe’ বিশ্বের বিভিন্ন ভাষায় অনূদিত হয়েছে।\";s:9:\"answer_id\";N;s:10:\"subject_id\";i:85;s:7:\"chapter\";N;s:10:\"topic_name\";s:15:\"General Science\";s:8:\"category\";s:3:\"MCQ\";s:8:\"board_id\";N;s:4:\"year\";s:2:\"46\";s:5:\"class\";N;s:14:\"institution_id\";i:4;s:6:\"image1\";N;s:6:\"image2\";N;s:6:\"image3\";N;s:6:\"image4\";N;s:7:\"user_id\";N;s:11:\"is_verified\";i:0;s:10:\"created_at\";s:19:\"2026-01-29 23:15:16\";s:10:\"updated_at\";s:19:\"2026-01-29 23:15:16\";s:10:\"was_viewed\";i:0;}s:11:\"\0*\0original\";a:26:{s:2:\"id\";i:5240;s:7:\"article\";s:139:\"কৃষ্ণগহ্বর নিয়ে কোন বাঙালি বিজ্ঞানী গবেষণা করেছেন?\";s:1:\"a\";s:32:\"কুদরত-ই-খুদা\";s:1:\"b\";s:50:\"কাজী মোতাহার হোসেন\";s:1:\"c\";s:47:\"জামাল নজরুল ইসলাম\";s:1:\"d\";s:50:\"আব্