(5804, 'v = (6t² + 3t) ms⁻¹ হলে 3s পরে বস্তুর সরণ কত?', 'v=(6t²+3t)ms⁻¹হলে3sপরেবস্তুরসরণকত?', '90 m', '90m', '67.5 m', '63 m', '27 m', 'খ', '$s = \\int v dt = \\int (6t^2 + 3t) dt = 2t^3 + 1.5t^2$ <br> $t=3$ হলে, $s = 2(27) + 1.5(9) = 54 + 13.5 = 67.5  m$।', NULL, 6, 3, 'বস্তুর সরণ নির্ণয়', 'MCQ', '8', '2025', NULL, 2, NULL, NULL, NULL, NULL, 1, 1, 0, '2026-03-04 09:38:57', '2026-05-09 09:52:40', 0),
(5805, 'রাস্তার ব্যাংকিং নির্ভর করে—\ni. বাঁকের ব্যাসার্ধের ওপর\nii. গাড়ির ভরের ওপর\niii. গাড়ির বেগের ওপর', 'রাস্তারব্যাংকিংনির্ভরকরে—i.বাঁকেরব্যাসার্ধেরওপরii.গাড়িরভরেরওপরiii.গাড়িরবেগেরওপর', 'i ও ii', 'iওii', 'i ও iii', 'ii ও iii', 'i, ii ও iii', 'খ', 'ব্যাংকিং কোণের সমীকরণ $\\tan\\theta = v^2/rg$। এখানে $v$ (বেগ) এবং $r$ (ব্যাসার্ধ) আছে, কিন্তু ভর ($m$) নেই।', NULL, 6, 4, 'রাস্তার ব্যাংকিং', 'MCQ', '8', '2025', NULL, 2, NULL, NULL, NULL, NULL, 1, 1, 0, '2026-03-04 09:38:57', '2026-05-15 03:41:03', 0),
