INSERT INTO `subjects` (`id`, `name`, `bangla`, `banglish`, `class`, `institution_id`, `year`, `exam_at`, `description`, `slug`, `status`, `chapters`) VALUES
(1, 'Bangla 1st', 'বাংলা ১ম পত্র', 'bangla 1st', '', 2, 2025, NULL, NULL, 'bangla-1st', 1, '[\"1. অপরিচিতা\", \"2. বিলাসি\", \"3. আমার পথ\", \"4. মানব-কল্যাণ\", \"5. মাসি-পিসি\", \"6. বায়ান্নর দিনগুলি\", \"7. রেইনকোট\", \"8. মহাজাগতিক কিউরেটর\", \"9. নেকলেস\", \"10. গৃহ\", \"11. আহ্বান\", \"12. জীবন ও বৃক্ষ\", \"13. বিভীষণের প্রতি মেঘনাদ\", \"14. সোনার তরী\", \"15. বিদ্রোহী\", \"16. প্রতিদান\", \"17. সুচেতনা\", \"18. তাহারেই পড়ে মনে\", \"19. পদ্মা\", \"20. আঠারো বছর বয়স\", \"21. ফেব্রুয়ারি ১৯৬৯\", \"22. আমি কিংবদন্তির কথা বলছি\", \"23. নূরলদীনের কথা মনে পড়ে যায়\", \"24. ছবি\", \"25. লালসালু\", \"26. সিরাজউদ্দৌলা\"]'),
(2, 'Bangla 2nd', 'বাংলা ২য় পত্র', 'bangla 2nd', '', 2, 2025, NULL, NULL, 'bangla-2nd', 1, '[\"1. বাংলা উচ্চারণের নিয়ম\", \"2. বাংলা বানানের নিয়ম\", \"3. বাংলা ভাষার ব্যাকরণিক শব্দশ্রেণি\", \"4. বাংলা শব্দ গঠন (উপসর্গ ও সমাস)\", \"5. বাক্যতত্ত্ব\", \"6. বাংলা ভাষার অপপ্রয়োগ ও শুদ্ধ প্রয়োগ\", \"7. পারিভাষিক শব্দ\", \"8. অনুবাদ\", \"9. দিনলিপি লিখন\", \"10. প্রতিবেদন রচনা\", \"11. বৈদ্যুতিন চিঠি (E-mail)\", \"12. খুদে বার্তা (SMS)\", \"13. আবেদনপত্র\", \"14. সারসংক্ষেপ ও সারমর্ম\", \"15. ভাব-সম্প্রসারণ\", \"16. সংলাপ (Dialogue)\", \"17. ক্ষুদে গল্প লিখন\", \"18. প্রবন্ধ-নিবন্ধ রচনা\"]'),
(3, 'English 1st', 'ইংরেজি ১ম পত্র', 'english 1st', '', 2, 2025, NULL, NULL, 'english-1st', 1, '[\"1. People or Institutions Making History\", \"2. Dreams\", \"3. What is a Dream?\", \"4. Human Relationships\", \"5. Adolescence\", \"6. Adulthood and Education\", \"7. Human Rights\", \"8. Environment and Nature\", \"9. Diaspora\", \"10. Peace and Conflict\", \"11. Tours and Travels\", \"12. Art and Music\", \"13. Myths and Fables\", \"14. Personalities\"]'),
(4, 'English 2nd', 'ইংরেজি দ্বিতীয় পত্র', 'english 2nd', '', 2, 2025, NULL, NULL, 'english-2nd', 1, '[\"1. Punctuation\", \"2. Articles\", \"3. Use of Appropriate Prepositions\", \"4. Special Uses of Some Words and Phrases\", \"5. Right Form of Verbs\", \"6. Subject-Verb Agreement\", \"7. Narrative Style (Direct and Indirect Speech)\", \"8. Modifiers\", \"9. Sentence Connectors\", \"10. Synonym and Antonym\", \"11. Changing Sentences (Voice, Degree, Structure)\", \"12. Pronoun Referencing\", \"13. Formal Letter (Complaint, Inquiry, Order)\", \"14. E-mail Writing\", \"15. Report Writing\", \"16. Paragraph Writing (Listing, Comparison, Cause-Effect)\", \"17. Composition Writing\"]'),
(5, 'ICT', 'আইসিটি', 'ict', '', 2, 2025, NULL, NULL, 'ict', 1, '[\"1. তথ্য ও যোগাযোগ প্রযুক্তি: বিশ্ব ও বাংলাদেশ প্রেক্ষিত\", \"2. কমিউনিকেশন সিস্টেমস ও নেটওয়ার্কিং\", \"3. সংখ্যা পদ্ধতি ও ডিজিটাল ডিভাইস\", \"4. ওয়েব ডিজাইন পরিচিতি ও এইচটিএমএল (HTML)\", \"5. প্রোগ্রামিং ভাষা\", \"6. ডেটাবেজ ম্যানেজমেন্ট সিস্টেম\"]'),
(6, 'Physics 1st', 'পদার্থ বিজ্ঞান ১ম পত্র', 'podartho 1st', '', 2, 2025, NULL, NULL, 'physics-1st', 1, '[\"1. ভৌত জগৎ ও পরিমাপ\", \"2. ভেক্টর\", \"3. গতিবিদ্যা\", \"4. নিউটনীয় বলবিদ্যা\", \"5. কাজ, শক্তি ও ক্ষমতা\", \"6. মহাকর্ষ ও অভিকর্ষ\", \"7. পদার্থের গাঠনিক ধর্ম\", \"8. পর্যাবৃত্ত গতি\", \"9. তরঙ্গ\", \"10. আদর্শ গ্যাস ও গ্যাসের গতিতত্ত্ব\"]'),
(7, 'Physics 2nd', 'পদার্থ বিজ্ঞান  ২য় পত্র', 'podartho 2nd', '', 2, 2025, NULL, NULL, 'physics-2nd', 1, '[\"1. তাপগতিবিদ্যা\", \"2. স্থির তড়িৎ\", \"3. চল তড়িৎ\", \"4. তড়িৎ প্রবাহের চৌম্বক ক্রিয়া ও চৌম্বকত্ব\", \"5. তাড়িতচৌম্বক আবেশ ও পরিবর্তী প্রবাহ\", \"6. জ্যামিতিক আলোকবিজ্ঞান\", \"7. ভৌত আলোকবিজ্ঞান\", \"8. আধুনিক পদার্থবিজ্ঞানের সূচনা\", \"9. পরমাণুর মডেল ও নিউক্লীয় পদার্থবিজ্ঞান\", \"10. সেমিকন্ডাক্টর ও ইলেকট্রনিক্স\", \"11. জ্যোতির্বিজ্ঞান\"]'),
(8, 'Bangla', 'বাংলা', 'bangla', '', 4, 10, NULL, NULL, 'bangla', 1, '[\"1. বাংলা সাহিত্যের যুগবিভাগ (প্রাচীন, মধ্য, আধুনিক)\",\"2. চর্যাপদ (প্রাচীন যুগ)\",\"3. অন্ধকার যুগ ও তুর্কি বিজয়\",\"4. শ্রীকৃষ্ণকীর্তন কাব্য\",\"5. বৈষ্ণব পদাবলি\",\"6. মঙ্গলকাব্য (মনসামঙ্গল, চণ্ডীমঙ্গল, অন্নদামঙ্গল)\",\"7. অনুবাদ সাহিত্য (রামায়ণ, মহাভারত, ভাগবত)\",\"8. রোমান্টিক প্রণয়োপখ্যান (শাহ মুহম্মদ সগীর, আলাওল)\",\"9. আরাকান রাজসভা ও নাথ সাহিত্য\",\"10. মসিয়া সাহিত্য ও শাক্ত পদাবলি\",\"11. লোকসাহিত্য ও ময়মনসিংহ গীতিকা\",\"12. ফোর্ট উইলিয়াম কলেজ ও গদ্যের বিকাশ\",\"13. সাময়িকপত্র ও পত্রিকা\",\"14. ঈশ্বরচন্দ্র বিদ্যাসাগর\",\"15. মাইকেল মধুসূদন দত্ত\",\"16. বঙ্কিমচন্দ্র চট্টোপাধ্যায়\",\"17. রবীন্দ্রনাথ ঠাকুর\",\"18. কাজী নজরুল ইসলাম\",\"19. মীর মশাররফ হোসেন ও দীনবন্ধু মিত্র\",\"20. শরৎচন্দ্র চট্টোপাধ্যায়\",\"21. জীবনানন্দ দাশ ও জসীমউদ্দীন\",\"22. কায়কোবাদ ও ফররুখ আহমদ\",\"23. সুফিয়া কামাল ও বেগম রোকেয়া\",\"24. আখতারুজ্জামান ইলিয়াস ও শওকত ওসমান\",\"25. সেলিনা হোসেন ও হুমায়ূন আহমেদ\",\"26. মুনীর চৌধুরী ও জহির রায়হান\",\"27. দ্বিজেন্দ্রলাল রায়\",\"28. সত্যেন্দ্রনাথ দত্ত\",\"29. বিভূতিভূষণ বন্দ্যোপাধ্যায়\",\"30. মানিক বন্দ্যোপাধ্যায়\",\"31. তারাশঙ্কর বন্দ্যোপাধ্যায়\",\"32. বাংলা নাটক, ছোটগল্প ও প্রবন্ধ\",\"33. গুরুত্বপূর্ণ গ্রন্থ ও সাহিত্যকর্ম\",\"34. ভাষা আন্দোলন ও মুক্তিযুদ্ধ ভিত্তিক সাহিত্য\",\"35. বাংলা সাহিত্যের গুরুত্বপূর্ণ উপাধি, প্রথম ও প্রবর্তক\",\"36. ভাষা, উপভাষা ও সাধু-চলিত রীতি\",\"37. ধ্বনিতত্ত্ব (ধ্বনি, বর্ণ ও ধ্বনির পরিবর্তন)\",\"38. রূপতত্ত্ব (শব্দ, পদের শ্রেণিবিভাগ)\",\"39. লিঙ্গ ও বচন\",\"40. উপসর্গ ও অনুসর্গ\",\"41. সন্ধি\",\"42. সমাস\",\"43. কারক ও বিভক্তি\",\"44. প্রকৃতি ও প্রত্যয়\",\"45. বাক্যতত্ত্ব (বাক্য প্রকরণ ও যতি চিহ্ন)\",\"46. বাগধারা ও প্রবাদ-প্রবচন\",\"47. এক কথায় প্রকাশ\",\"48. সমার্থক ও বিপরীতার্থক শব্দ\",\"49. বানান ও বাক্য শুদ্ধিকরণ\",\"50. পারিভাষিক শব্দ ও অনুবাদ\"]'),
(9, 'English', 'ইংরেজি', 'english', '', 4, 10, NULL, NULL, 'english', 1, '[\"1. Parts of Speech (Overview)\",\"2. Noun\",\"3. Pronoun\",\"4. Adjective\",\"5. Verb (Finite & Non-Finite)\",\"6. Gerund, Participle & Infinitive\",\"7. Adverb\",\"8. Preposition\",\"9. Conjunction\",\"10. Interjection\",\"11. Number (Singular & Plural)\",\"12. Gender\",\"13. Articles (A, An, The)\",\"14. Tense\",\"15. Voice (Active & Passive)\",\"16. Narration (Direct & Indirect Speech)\",\"17. Subject-Verb Agreement\",\"18. Sentence Structure & Types of Sentences\",\"19. Clauses & Phrases\",\"20. Transformation of Sentences\",\"21. Degree Change\",\"22. Conditional Sentences\",\"23. Modals & Semi-Modals\",\"24. Right Form of Verbs\",\"25. Use of Appropriate Prepositions\",\"26. Punctuation\",\"27. Spelling & Common Errors\",\"28. Correction of Sentences\",\"29. Synonyms\",\"30. Antonyms\",\"31. One Word Substitution\",\"32. Idioms & Phrases\",\"33. Phrasal Verbs / Group Verbs\",\"34. Proverbs\",\"35. Analogy\",\"36. Foreign Words & Phrases\",\"37. Prefix & Suffix\",\"38. Root Words\",\"39. Reading Comprehension\",\"40. Cloze Test & Fill in the Blanks\",\"41. Sentence Completion\",\"42. Rearrangement & Para Jumbles\",\"43. Translation (Bangla to English & English to Bangla)\",\"44. Writing (Essay, Letter, Email, Precis, Report)\",\"45. English Literature: Periods & History\",\"46. William Shakespeare\",\"47. Major Poets, Dramatists & Novelists\",\"48. Romantic & Victorian Era Literature\",\"49. Modern & Post-Modern Literature\",\"50. Literary Terms, Quotes & Characters\"]'),
(10, 'Bangladesh affairs', 'বাংলাদেশ বিষয়াবলী', 'bangladesh affairs', '', 4, 10, NULL, NULL, 'bangladesh-affairs', 1, '[\"1. বাংলাদেশ পরিচিতি (অবস্থান, সীমানা, আয়তন)\",\"2. ভূপ্রকৃতি, নদ-নদী ও জলবায়ু\",\"3. বাংলাদেশের প্রাকৃতিক সম্পদ (খনিজ, বনজ, মৎস্য)\",\"4. জনসংখ্যা, জাতিগোষ্ঠী ও নৃগোষ্ঠী\",\"5. প্রাচীন বাংলার ইতিহাস\",\"6. মুসলিম শাসনামল (সুলতানি ও মুঘল যুগ)\",\"7. ব্রিটিশ শাসনামল ও নবজাগরণ\",\"8. পাকিস্তান আমল (১৯৪৭-১৯৭০)\",\"9. ভাষা আন্দোলন (১৯৫২)\",\"10. যুক্তফ্রন্ট ও ছয় দফা আন্দোলন (১৯৬৬)\",\"11. আগরতলা ষড়যন্ত্র মামলা ও গণঅভ্যুত্থান (১৯৬৯)\",\"12. সাধারণ নির্বাচন (১৯৭০)\",\"13. মুক্তিযুদ্ধ ও স্বাধীনতা ঘোষণা (১৯৭১)\",\"14. মুজিবনগর সরকার ও প্রশাসনিক কাঠামো\",\"15. মুক্তিযুদ্ধের সেক্টর, বাহিনী ও ক্র্যাক প্লাটুন\",\"16. বীর মুক্তিযোদ্ধা ও খেতাবপ্রাপ্ত ব্যক্তিবর্গ\",\"17. বঙ্গবন্ধু শেখ মুজিবুর রহমান: জীবন ও রাজনৈতিক দর্শন\",\"18. বাংলাদেশের সংবিধান (ইতিহাস ও বৈশিষ্ট্য)\",\"19. সংবিধানের গুরুত্বপূর্ণ অনুচ্ছেদ ও সংশোধনী\",\"20. জাতীয় সংসদ (আইনসভা)\",\"21. নির্বাহী বিভাগ (রাষ্ট্রপতি, প্রধানমন্ত্রী ও মন্ত্রিসভা)\",\"22. বিচার বিভাগ (সুপ্রিম কোর্ট ও নিম্ন আদালত)\",\"23. নির্বাচন ব্যবস্থা ও নির্বাচন কমিশন\",\"24. স্থানীয় সরকার ও প্রশাসন ব্যবস্থা (জেলা, উপজেলা)\",\"25. বাংলাদেশের জাতীয় প্রতীক, পতাকা ও মানচিত্র\",\"26. কৃষি ও প্রাকৃতিক সম্পদ (ফসল, প্রাণিজ)\",\"27. শিল্প ও বাণিজ্য (পোশাক শিল্প ও রপ্তানি)\",\"28. অর্থনীতি, বাজেট ও রাজস্ব ব্যবস্থা\",\"29. ব্যাংকিং, বিমা ও আর্থিক প্রতিষ্ঠান\",\"30. দারিদ্র্য বিমোচন ও উন্নয়ন সূচক (SDG)\",\"31. শিক্ষা, সাহিত্য ও সংস্কৃতি\",\"32. স্বাস্থ্য ব্যবস্থা ও জনস্বাস্থ্য\",\"33. তথ্য ও যোগাযোগ প্রযুক্তি (ICT) ও ডিজিটাল বাংলাদেশ\",\"34. পরিবেশ, জলবায়ু ও দুর্যোগ ব্যবস্থাপনা\",\"35. যোগাযোগ ব্যবস্থা (মেগা প্রকল্প: পদ্মা সেতু, মেট্রোরেল)\",\"36. জ্বালানি ও বিদ্যুৎ খাত\",\"37. প্রতিরক্ষা ও নিরাপত্তা ব্যবস্থা\",\"38. পররাষ্ট্রনীতি ও দ্বিপাক্ষিক সম্পর্ক\",\"39. আন্তর্জাতিক সংস্থায় বাংলাদেশ (UN, OIC, SAARC)\",\"40. ক্রীড়া ও ক্রীড়াঙ্গন (ক্রিকেট, ফুটবল, অলিম্পিক)\",\"41. জাতীয় পুরস্কার ও সম্মাননা (স্বাধীনতা ও একুশে পদক)\",\"42. শিল্পকলা, স্থাপত্য ও ঐতিহ্যবাহী স্থান\",\"43. বাংলাদেশের প্রত্নতাত্ত্বিক নিদর্শন\",\"44. উপজাতি ও ক্ষুদ্র নৃগোষ্ঠীর সংস্কৃতি\",\"45. নারী ও শিশু উন্নয়ন বিষয়ক কর্মসূচি\",\"46. সংবাদমাধ্যম ও গণমাধ্যম\",\"47. ঐতিহাসিক স্থান ও পর্যটন কেন্দ্র\",\"48. বাংলাদেশের জাতীয় দিবসসমূহ\",\"49. বরেণ্য ব্যক্তিত্ব ও তাঁদের অবদান\",\"50. মুক্তিযুদ্ধভিত্তিক চলচ্চিত্র, উপন্যাস ও সাহিত্য\",\"51. সাম্প্রতিক বাংলাদেশ ও কারেন্ট অ্যাফেয়ার্স\"]'),
(11, 'International affairs', 'আন্তর্জাতিক বিষয়াবলী', 'antorjatik', '', 4, 10, NULL, NULL, 'international-affairs', 1, '[\"1. আন্তর্জাতিক সম্পর্কের ধারণা, তত্ত্ব ও শক্তি\",\"2. বিশ্ব রাজনীতি ও ভূ-রাজনীতির ইতিহাস\",\"3. আন্তর্জাতিক সংস্থা: পরিচিতি, গঠন ও বিবর্তন\",\"4. জাতিসংঘ (UN): সচিবালয়, অঙ্গসংগঠন ও বিশেষায়িত সংস্থা\",\"5. নিরাপত্তা পরিষদ ও সাধারণ পরিষদের ভূমিকা\",\"6. আন্তর্জাতিক আর্থিক প্রতিষ্ঠান (IMF, World Bank, ADB, NDB)\",\"7. বিশ্ব বাণিজ্য সংস্থা (WTO) ও বৈশ্বিক বাণিজ্য নীতি\",\"8. আঞ্চলিক সংস্থা (SAARC, ASEAN, BIMSTEC, EU, AU, OIC)\",\"9. সামরিক ও নিরাপত্তা জোট (NATO, AUKUS, QUAD)\",\"10. জোট নিরপেক্ষ আন্দোলন (NAM) ও কমনওয়েলথ\",\"11. অর্থনৈতিক ও রাজনৈতিক গোষ্ঠী (G7, G20, BRICS, D-8)\",\"12. আন্তর্জাতিক আইন, সমুদ্র আইন (UNCLOS) ও মানবাধিকার\",\"13. আন্তর্জাতিক আদালত ও ট্রাইব্যুনাল (ICJ, ICC, PCA)\",\"14. কূটনীতি, পররাষ্ট্রনীতি ও শক্তিধর রাষ্ট্রসমূহের প্রভাব (USA, China, Russia)\",\"15. দক্ষিণ এশিয়া ও দক্ষিণ-পূর্ব এশিয়ার রাজনীতি\",\"16. মধ্যপ্রাচ্যের ভূ-রাজনীতি ও সংকটসমূহ\",\"17. ইউরোপীয় রাজনীতি ও ব্রেক্সিট পরবর্তী ইউনিয়ন\",\"18. ইন্দো-প্যাসিফিক কৌশল ও দক্ষিণ চীন সাগর বিরোধ\",\"19. বেল্ট অ্যান্ড রোড ইনিশিয়েটিভ (BRI) ও বৈশ্বিক কানেক্টিভিটি\",\"20. রাশিয়া-ইউক্রেন যুদ্ধ ও এর ভূ-রাজনৈতিক প্রভাব\",\"21. ইসরায়েল-ফিলিস্তিন সংঘাত ও আরব-ইসরায়েল সম্পর্ক\",\"22. যুক্তরাষ্ট্র-চীন বাণিজ্য যুদ্ধ ও দ্বিপাক্ষিক সম্পর্ক\",\"23. বৈশ্বিক সন্ত্রাসবাদ, জঙ্গিবাদ ও সাইবার নিরাপত্তা\",\"24. পারমাণবিক অস্ত্র, নিরস্ত্রীকরণ ও এনপিটি (NPT)\",\"25. জলবায়ু পরিবর্তন, প্যারিস চুক্তি ও কোপ (COP) সম্মেলন\",\"26. টেকসই উন্নয়ন লক্ষ্যমাত্রা (SDGs) ও এমডিজি (MDGs)\",\"27. অভিবাসন, শরণার্থী সমস্যা ও বৈশ্বিক মানবাধিকার পরিস্থিতি\",\"28. বৈশ্বিক স্বাস্থ্য রাজনীতি (WHO) ও অতিমারি মোকাবিলা\",\"29. বৈশ্বিক জ্বালানি রাজনীতি (OPEC) ও খনিজ সম্পদ\",\"30. বিখ্যাত চুক্তি, সনদ, কনভেনশন ও প্রটোকল\",\"31. আন্তর্জাতিক সংবাদ সংস্থা ও বৈশ্বিক গণমাধ্যম\",\"32. বিভিন্ন দেশের গোয়েন্দা সংস্থা, পার্লামেন্ট ও মুদ্রা\",\"33. ভৌগোলিক উপনাম, প্রণালী ও গুরুত্বপূর্ণ সীমারেখা\",\"34. বৈশ্বিক অর্থনৈতিক সংকট ও মুদ্রাস্ফীতি\",\"35. আন্তর্জাতিক বিরোধ, সীমান্ত সমস্যা ও ছিটমহল\",\"36. আন্তর্জাতিক পুরস্কার, সম্মাননা (নোবেল, অস্কার) ও পদক\",\"37. গুরুত্বপূর্ণ আন্তর্জাতিক দিবস ও তাৎপর্য\",\"38. বিখ্যাত ব্যক্তিত্ব ও বিশ্ববরেণ্য রাষ্ট্রনায়ক\",\"39. মহাকাশ গবেষণা ও প্রযুক্তির ভূ-রাজনীতি\",\"40. সামুদ্রিক নিরাপত্তা, নৌ-কৌশল ও গুরুত্বপূর্ণ জলপথ\",\"41. বৈশ্বিক উন্নয়ন সংস্থা ও এনজিও (UNDP, UNICEF, ICRC)\",\"42. সাম্প্রতিক বিশ্ব ও সমসাময়িক ঘটনাপ্রবাহ (Current Affairs)\"]'),
(12, 'Geography', 'ভূগোল', 'vugol', '', 4, 10, NULL, NULL, 'geography', 1, '[\"1. ভূগোলের পরিচিতি, শাখা ও জ্যোতির্বিজ্ঞান (সৌরজগৎ)\",\"2. পৃথিবীর গঠন ও অভ্যন্তরীণ স্তরসমূহ (ক্রাস্ট, ম্যান্টল, কোর)\",\"3. পৃথিবীর আকার, আয়তন ও গতি (আহ্নিক ও বার্ষিক)\",\"4. অক্ষাংশ, দ্রাঘিমাংশ, সময় গণনা ও আন্তর্জাতিক তারিখ রেখা\",\"5. মানচিত্র পঠন, স্কেল ও দিকনির্ণয় কৌশল\",\"6. ভূ-আকৃতি বিদ্যা: প্লেট টেকটনিকস ও মহাদেশীয় সঞ্চরণ তত্ত্ব\",\"7. শিলা ও খনিজ: প্রকারভেদ ও বৈশিষ্ট্য\",\"8. আগ্নেয়গিরি, ভূমিকম্প ও সুনামি\",\"9. ভূমিরূপের পরিবর্তন: পর্বত, মালভূমি ও সমভূমি\",\"10. নদ-নদী: ক্ষয় ও অবক্ষেপণ প্রক্রিয়া ও সংশ্লিষ্ট ভূমিরূপ\",\"11. বায়ুমণ্ডল: গঠন, স্তরবিন্যাস ও ওজোন স্তর\",\"12. বায়ুর তাপমাত্রা, চাপবলয় ও বৈশ্বিক বায়ুপ্রবাহ\",\"13. বারিপাত (বৃষ্টিপাত), জলচক্র ও আর্দ্রতা\",\"14. মহাসাগরীয় ভূপ্রকৃতি, স্রোত ও জোয়ার-ভাটা\",\"15. মৃত্তিকা (Soil): গঠন, প্রকারভেদ ও ক্ষয়\",\"16. প্রাকৃতিক উদ্ভিদ ও বন্যপ্রাণী (বিশ্ব ও বাংলাদেশ)\",\"17. জীবমণ্ডল, বাস্তুতন্ত্র (Ecosystem) ও পরিবেশ\",\"18. জলবায়ু পরিবর্তন: গ্রিনহাউস প্রভাব ও বৈশ্বিক উষ্ণায়ন\",\"19. প্রাকৃতিক দুর্যোগের প্রকারভেদ ও দুর্যোগ ব্যবস্থাপনা চক্র\",\"20. পরিবেশ দূষণ, বর্জ্য ব্যবস্থাপনা ও পরিবেশ সংরক্ষণ\",\"21. বিশ্ব জলবায়ু অঞ্চল ও বনজ সম্পদ\",\"22. জনসংখ্যা ভূগোল: বৃদ্ধি, ঘনত্ব, বণ্টন ও জনমিতিক রূপান্তর\",\"23. নগরায়ণ, অভিবাসন ও জনবসতির ধরন\",\"24. কৃষি ভূগোল: প্রধান ফসল ও বিশ্ব কৃষি অঞ্চল\",\"25. প্রাকৃতিক সম্পদ: খনিজ, পানি ও বনজ সম্পদ\",\"26. জ্বালানি সম্পদ (কয়লা, তেল, গ্যাস ও নবায়নযোগ্য শক্তি)\",\"27. শিল্প ও অর্থনৈতিক ভূগোল: উন্নত ও উন্নয়নশীল বিশ্ব\",\"28. পরিবহন, যোগাযোগ ও বিশ্ব বাণিজ্যিক রুট\",\"29. আঞ্চলিক ভূগোল: এশিয়া, ইউরোপ ও আমেরিকা\",\"30. আঞ্চলিক ভূগোল: আফ্রিকা, ওশেনিয়া ও মেরু অঞ্চল\",\"31. বাংলাদেশের ভৌগোলিক অবস্থান, সীমানা ও ভূ-রাজনীতি\",\"32. বাংলাদেশের ভূপ্রকৃতি ও অঞ্চলসমূহ\",\"33. বাংলাদেশের নদ-নদী, হাওর ও জলাভূমি ব্যবস্থা\",\"34. বাংলাদেশের জলবায়ু ও মৌসুমি বায়ুর প্রভাব\",\"35. বাংলাদেশের প্রাকৃতিক সম্পদ (খনিজ ও বনজ)\",\"36. সুন্দরবন ও বাংলাদেশের বনাঞ্চল রক্ষা\",\"37. বাংলাদেশের কৃষি: ফসল, মৎস্য ও প্রাণিসম্পদ\",\"38. বাংলাদেশের জনসংখ্যা, নৃগোষ্ঠী ও জনমিতি\",\"39. বাংলাদেশের শিল্প, বাণিজ্য ও অর্থনৈতিক অঞ্চল\",\"40. বাংলাদেশের যোগাযোগ ও মেগা প্রজেক্ট (পদ্মা সেতু, টানেল)\",\"41. বাংলাদেশের দুর্যোগ ও ঝুঁকি ব্যবস্থাপনা (বন্যা, ঘূর্ণিঝড়)\",\"42. বদ্বীপ পরিকল্পনা (Delta Plan 2100) ও নদী শাসন\",\"43. বাংলাদেশের পরিবেশ নীতি ও টেকসই উন্নয়ন\",\"44. সমুদ্র বিজয় ও ব্লু-ইকোনমি (Blue Economy)\",\"45. মানচিত্র চর্চা (বিশ্ব ও বাংলাদেশ)\",\"46. মহাকাশ গবেষণা ও রিমোট সেন্সিং (স্পারসো)\",\"47. গ্লোবাল পজিশনিং সিস্টেম (GPS) ও GIS ধারণা\",\"48. আন্তর্জাতিক পরিবেশ চুক্তি ও প্রটোকল (কিয়োটো, প্যারিস)\",\"49. বিখ্যাত ভৌগোলিক উপনাম ও স্থান\",\"50. সাম্প্রতিক ভূগোল ও পরিবেশ বিষয়াবলি (Current Affairs)\"]'),
(13, 'General Science', 'সাধারণ বিজ্ঞান', 'biggan', '', 4, 10, NULL, NULL, 'general-science', 1, '[\"1. বিজ্ঞানের পরিচিতি, বৈজ্ঞানিক যন্ত্র ও একক\",\"2. পদার্থের অবস্থা, গঠন (পরমাণু ও অণু) ও তেজস্ক্রিয়তা\",\"3. পর্যায় সারণি, ধাতু ও অধাতুর ধর্ম\",\"4. মৌল, যৌগ, মিশ্রণ ও রাসায়নিক বিক্রিয়া\",\"5. অম্ল, ক্ষার, লবণ ও pH এর ধারণা\",\"6. ভৌত ও রাসায়নিক পরিবর্তন এবং জারণ-বিজারণ\",\"7. বল (Force), কাজ, ক্ষমতা ও শক্তি\",\"8. নিউটনের গতিসূত্র, মহাকর্ষ ও মাধ্যাকর্ষণ\",\"9. স্থিতিবিদ্যা ও গতিবিদ্যা (সরল দোলক ও লিভার)\",\"10. পদার্থের সাধারণ ধর্ম (পৃষ্ঠটান, সান্দ্রতা ও আর্কিমিডিসের সূত্র)\",\"11. তাপ ও তাপগতিবিদ্যা: সঞ্চালন ও সুপ্ততাপ\",\"12. স্থির বিদ্যুৎ, চল বিদ্যুৎ ও বৈদুতিক যন্ত্রাদি\",\"13. চুম্বকত্ব: প্রকারভেদ ও ডোমেইন তত্ত্ব\",\"14. তরঙ্গ ও শব্দ: প্রতিধ্বনি ও শব্দের বেগ\",\"15. আলো: প্রতিফলন, প্রতিসরণ ও বিচ্ছুরণ\",\"16. লেন্স ও চোখের ত্রুটি (হ্রস্বদৃষ্টি ও দীর্ঘদৃষ্টি)\",\"17. আধুনিক পদার্থবিজ্ঞান: এক্স-রে, তেজস্ক্রিয়তা ও কোয়ান্টাম তত্ত্ব\",\"18. ইলেকট্রনিক্স: সেমিকন্ডাক্টর, ট্রানজিস্টর ও আইসি (IC)\",\"19. সৌরজগৎ, পৃথিবী ও মহাকাশ বিজ্ঞান\",\"20. জীববিজ্ঞানের পরিচিতি ও শ্রেণিবিন্যাস (Taxonomy)\",\"21. কোষ (Cell): গঠন, কাজ ও বিভাজন (মাইটোসিস ও মিয়োসিস)\",\"22. টিস্যু (Tissue) ও অঙ্গসংস্থান বিদ্যা\",\"23. মানবদেহ-১: কঙ্কালতন্ত্র, পেশিতন্ত্র ও পরিপাকতন্ত্র\",\"24. মানবদেহ-২: রক্ত ও সংবহনতন্ত্র (হৃৎপিণ্ড ও রক্তচাপ)\",\"25. মানবদেহ-৩: শ্বসনতন্ত্র, রেচনতন্ত্র ও ত্বক\",\"26. মানবদেহ-৪: স্নায়ুতন্ত্র, মস্তিষ্ক ও জ্ঞানেন্দ্রিয় (চোখ, কান)\",\"27. হরমোন, এনজাইম ও গ্রন্থিতন্ত্র\",\"28. উদ্ভিদবিদ্যা: সালোকসংশ্লেষণ, প্রস্বেদন ও প্রজনন\",\"29. প্রাণীবিদ্যা ও মেরুদণ্ডী প্রাণীর শ্রেণিবিভাগ\",\"30. পুষ্টি ও খাদ্যবিজ্ঞান: ভিটামিন, খনিজ লবণ ও ক্যালরি\",\"31. রোগ ও রোগতত্ত্ব: ভাইরাস, ব্যাকটেরিয়া ও ছত্রাকজনিত রোগ\",\"32. অসংক্রামক ব্যাধি (ক্যান্সার, ডায়াবেটিস) ও প্রতিরোধ\",\"33. জিনতত্ত্ব (Genetics), ডিএনএ (DNA) ও আরএনএ (RNA)\",\"34. বিবর্তন ও জীবের বংশগতি\",\"35. পরিবেশ বিজ্ঞান ও বাস্তুতন্ত্র (Ecology)\",\"36. জীববৈচিত্র্য ও বন্যপ্রাণী সংরক্ষণ\",\"37. বায়োটেকনোলজি: টিস্যু কালচার ও জেনেটিক ইঞ্জিনিয়ারিং\",\"38. কৃষিশিক্ষা ও মাটির উর্বরতা\",\"39. দৈনন্দিন জীবনে বিজ্ঞান (ব্যবহারিক বিজ্ঞান)\",\"40. আধুনিক রোগ নির্ণয় পদ্ধতি (CT Scan, MRI, ECG, Endoscopy)\",\"41. পলিমার, প্লাস্টিক ও তন্তু (Natural & Synthetic)\",\"42. সাবান, ডিটারজেন্ট ও কসমেটিকস রসায়ন\",\"43. পারমাণবিক শক্তি ও শক্তির বিকল্প উৎস\",\"44. নবায়নযোগ্য শক্তি ও পরিবেশবান্ধব প্রযুক্তি\",\"45. বায়ুমণ্ডল ও জলবায়ু পরিবর্তন (গ্রিনহাউস প্রভাব)\",\"46. প্রাকৃতিক দুর্যোগ ও দুর্যোগ ব্যবস্থাপনা\",\"47. তথ্য ও যোগাযোগ প্রযুক্তির বৈজ্ঞানিক ভিত্তি\",\"48. কৃত্রিম বুদ্ধিমত্তা ও রোবোটিক্স এর বিজ্ঞান\",\"49. সাম্প্রতিক বিজ্ঞান ও প্রযুক্তির অগ্রগতি\",\"50. সমসাময়িক বিজ্ঞান ও উদ্ভাবন (Current Affairs)\"]'),
(14, 'Computer', 'কম্পিউটার', 'computer', '', 4, 10, NULL, NULL, 'computer', 1, '[\"1. কম্পিউটারের ইতিহাস, প্রজন্ম ও বিবর্তন\",\"2. কম্পিউটারের প্রকারভেদ (Analog, Digital, Hybrid, Mainframe)\",\"3. কম্পিউটারের মৌলিক গঠন: ইনপুট, আউটপুট ও স্টোরেজ ডিভাইস\",\"4. সিপিইউ (CPU): কন্ট্রোল ইউনিট, ALU ও রেজিস্টার\",\"5. মাদারবোর্ড, বাস (Bus) ও পোর্ট (USB, HDMI)\",\"6. মেমোরি ও স্টোরেজ: RAM, ROM, Cache ও ফ্ল্যাশ মেমোরি\",\"7. সফটওয়্যার: সিস্টেম, অ্যাপ্লিকেশন ও ইউটিলিটি সফটওয়্যার\",\"8. অপারেটিং সিস্টেম (OS): উইন্ডোজ, লিনাক্স, ডস ও মোবাইল ওএস\",\"9. সংখ্যা পদ্ধতি: বাইনারি, অক্টাল, ডেসিমাল ও হেক্সাডেসিমাল\",\"10. সংখ্যা পদ্ধতির রূপান্তর ও পরিপূরক (2\'s Complement)\",\"11. লজিক গেট (AND, OR, NOT, NAND, NOR, XOR)\",\"12. বুলিয়ান অ্যালজেব্রা, এনকোডার ও ডিকোডার\",\"13. ডাটাবেজ ম্যানেজমেন্ট সিস্টেম (DBMS) ও এসকিউএল (SQL)\",\"14. ডেটা কমিউনিকেশন: মোড ও মেথড (Simplex, Duplex)\",\"15. কম্পিউটার নেটওয়ার্কিং: LAN, MAN, WAN ও টপোলজি\",\"16. নেটওয়ার্কিং ডিভাইস: হাব, সুইচ, রাউটার, গেটওয়ে ও মডেম\",\"17. ওএসআই (OSI) মডেল ও টিসিপি/আইপি (TCP/IP) প্রটোকল\",\"18. ইন্টারনেটের ইতিহাস, ডোমেইন, আইপি অ্যাড্রেস ও ডিএনএস (DNS)\",\"19. ওয়েবসাইট ডিজাইন ও ওয়েব টেকনোলজি (HTML, CSS, HTTP)\",\"20. ক্লাউড কম্পিউটিং: সার্ভিস মডেল ও স্টোরেজ\",\"21. সাইবার সিকিউরিটি: ভাইরাস, ম্যালওয়্যার, ফায়ারওয়াল ও হ্যাকিং\",\"22. ক্রিপ্টোগ্রাফি, ডিজিটাল সিগনেচার ও এনক্রিপশন\",\"23. ই-গভর্ন্যান্স, ডিজিটাল বাংলাদেশ ও স্মার্ট বাংলাদেশ রূপকল্প\",\"24. ই-কমার্স (B2B, B2C) ও অনলাইন পেমেন্ট গেটওয়ে\",\"25. সোশ্যাল মিডিয়া, ডিজিটাল প্ল্যাটফর্ম ও মেটাভার্স\",\"26. সার্চ ইঞ্জিন (Google, Bing, Pipilika) ও মেটা ট্যাগ\",\"27. কৃত্রিম বুদ্ধিমত্তা (AI) ও রোবোটিক্স এর প্রয়োগ\",\"28. মেশিন লার্নিং (ML), বিগ ডেটা (Big Data) ও ডেটা সায়েন্স\",\"29. ব্লকচেইন (Blockchain) ও ক্রিপ্টোকারেন্সি ধারণা\",\"30. ইন্টারনেট অব থিংস (IoT) ও স্মার্ট হোম টেকনোলজি\",\"31. ভার্চুয়াল রিয়েলিটি (VR) ও অগমেন্টেড রিয়েলিটি (AR)\",\"32. মোবাইল প্রযুক্তি: ১জি থেকে ৫জি ও স্মার্টফোন আর্কিটেকচার\",\"33. ওয়াইফাই (Wi-Fi), ব্লুটুথ ও ওয়াইম্যাক্স (WiMAX)\",\"34. স্যাটেলাইট কমিউনিকেশন ও বঙ্গবন্ধু স্যাটেলাইট-১\",\"35. মাল্টিমিডিয়া: অডিও, ভিডিও ফরম্যাট ও গ্রাফিক্স\",\"36. অফিস অ্যাপ্লিকেশন (MS Word, Excel, PowerPoint, Access)\",\"37. ফাইল এক্সটেনশন, শর্টকাট কী ও ব্যবহারিক আইসিটি\",\"38. প্রোগ্রামিং ভাষা (C, Python, Java) ও কম্পাইলার\",\"39. অ্যালগরিদম, ফ্লোচার্ট ও সিউডোকোড (Pseudocode)\",\"40. কম্পিউটার ট্রাবলশুটিং ও রক্ষণাবেক্ষণ\",\"41. বাংলাদেশের আইটি সেক্টর, ফ্রিল্যান্সিং ও আউটসোর্সিং\",\"42. হাই-টেক পার্ক ও আইটি ইনকিউবেশন সেন্টার\",\"43. সাইবার অপরাধ ও ডিজিটাল নিরাপত্তা আইন (২০১৮/২০২৩)\",\"44. তথ্য অধিকার আইন ও আইসিটি নীতিমালা\",\"45. প্রযুক্তির নৈতিকতা ও সামাজিক প্রভাব\",\"46. ওপেন সোর্স সফটওয়্যার ও ফ্রিওয়্যার ধারণা\",\"47. গ্লোবাল পজিশনিং সিস্টেম (GPS) ও জিআইএস (GIS)\",\"48. আধুনিক প্রিন্টিং প্রযুক্তি (3D Printing)\",\"49. সাম্প্রতিক আইসিটি অগ্রগতি ও বৈশ্বিক টেক জায়ান্ট\",\"50. সমসাময়িক আইসিটি ও কারেন্ট অ্যাফেয়ার্স\"]'),
(15, 'General Math', 'সাধারণ গনিত', 'gonit', '', 4, 10, NULL, NULL, 'general-math', 1, '[\"1. বাস্তব সংখ্যা, মূলদ ও অমূলদ সংখ্যার ধারণা\",\"2. ল.সা.গু ও গ.সা.গু (পাটিগণিত ও বীজগণিত)\",\"3. ভগ্নাংশ (সাধারণ ও দশমিক) ও সরলীকরণ\",\"4. ঐকিক নিয়ম, সময় ও কাজ, নল ও চৌবাচ্চা\",\"5. গড় (Average) ও বয়সের গাণিতিক সমস্যা\",\"6. অনুপাত ও সমানুপাত (Ratio & Proportion)\",\"7. শতকরা (Percentage) ও এর প্রয়োগ\",\"8. লাভ-ক্ষতি (Profit & Loss) ও কমিশন/ছাড়\",\"9. সরল ও যৌগিক মুনাফা (Simple & Compound Interest)\",\"10. মিশ্রণ ও অংশীদারী কারবার (Mixture & Partnership)\",\"11. গতিবেগ, সময় ও দূরত্ব (নৌকা, স্রোত ও ট্রেন)\",\"12. বীজগাণিতিক সূত্রাবলি ও মান নির্ণয়\",\"13. উৎপাদকে বিশ্লেষণ ও বহুপদী রাশির ব্যবহার\",\"14. সূচক ও লগারিদমের ধর্মাবলি ও প্রয়োগ\",\"15. সমান্তর ও গুণোত্তর ধারা (Series & Progressions)\",\"16. একঘাত ও দ্বিঘাত সমীকরণ এবং সমাধান\",\"17. অসমতা (Inequality) ও পরমমান (Absolute Value)\",\"18. সেট তত্ত্ব (Set Theory) ও ভেনচিত্রের প্রয়োগ\",\"19. বিন্যাস ও সমাবেশ (Permutation & Combination)\",\"20. সম্ভাবনা (Probability) ও দৈব চলক\",\"21. ফাংশন (Function) ও ডোমেইন-রেঞ্জ ধারণা\",\"22. জ্যামিতির মৌলিক ধারণা: রেখা, কোণ ও স্থানাঙ্ক জ্যামিতি\",\"23. ত্রিভুজ (Triangle): প্রকারভেদ, উপপাদ্য ও বৈশিষ্ট্য\",\"24. চতুর্ভুজ (Quadrilateral): সামান্তরিক, রম্বস ও ট্রাপিজিয়াম\",\"25. বৃত্ত (Circle): কেন্দ্র, জ্যা, ব্যাস ও স্পর্শক\",\"26. পিথাগোরাসের উপপাদ্য ও সমকোণী ত্রিভুজ\",\"27. পরিমিতি-১ (২ডি): ত্রিভুজ, চতুর্ভুজ ও বৃত্তের ক্ষেত্রফল\",\"28. পরিমিতি-২ (৩ডি): ঘনক, সিলিন্ডার ও গোলকের আয়তন\",\"29. ত্রিকোণমিতি: কোণের পরিমাপ ও অনুপাতসমূহ\",\"30. উচ্চতা ও দূরত্ব (Trigonometry Application)\",\"31. পরিসংখ্যান: গড়, মধ্যক, প্রচুরক ও বিস্তার পরিমাপ\",\"32. তথ্য উপস্থাপন: পাই-চার্ট, বার-গ্রাফ ও হিস্টোগ্রাম\",\"33. ঘড়ি ও ক্যালেন্ডার সংক্রান্ত গাণিতিক সমস্যা\",\"34. যুক্তিনির্ভর গাণিতিক সমস্যা (Logic Based Math)\",\"35. মৌলিক সংখ্যা ও বিভাজ্যতা যাচাইয়ের কৌশল\",\"36. গণিতের শর্টকাট টেকনিক ও ক্যালকুলেটর ছাড়া গণনার উপায়\",\"37. মানসিক গণিত (Mental Math) ও পাজল\",\"38. ক্যাডেট ও ব্যাংক নিয়োগ পরীক্ষার বিশেষ গণিত\",\"39. জ্যামিতিক অঙ্কন ও সম্পাদ্য বিষয়ক ধারণা\",\"40. পূর্ববর্তী বিসিএস ও পিএসসি পরীক্ষার প্রশ্ন বিশ্লেষণ\",\"41. লিখিত পরীক্ষার জন্য বিস্তারিত গাণিতিক সমাধান\",\"42. সাম্প্রতিক বিসিএস পরীক্ষার ট্রেন্ড ও মডেল টেস্ট\"]'),
(16, 'Mental ability', 'মানসিক দক্ষতা', 'manosik dokkhota', '', 4, 10, NULL, NULL, 'mental-ability', 1, '[\"1. মানসিক দক্ষতা ও আইকিউ (IQ) এর মৌলিক ধারণা\",\"2. ভাষাগত যৌক্তিক বিচার (Verbal Reasoning) ও শব্দ গঠন\",\"3. বানান ও ব্যাকরণিক শুদ্ধি যাচাই\",\"4. সমার্থক, বিপরীতার্থক ও জোড়া শব্দের যৌক্তিক সম্পর্ক\",\"5. সংখ্যা ও অক্ষরের ধারা (Number & Letter Series) সম্পন্নকরণ\",\"6. আলফা-নিউমেরিক কোডিং ও ডিকোডিং (Coding-Decoding)\",\"7. সাদৃশ্য বিচার (Analogy) ও শ্রেণিবিন্যাস (Classification)\",\"8. অদল-বদল (Odd One Out) ও অমিল খুঁজে বের করা\",\"9. রক্ত সম্পর্ক (Blood Relations) ও পারিবারিক বৃক্ষ অঙ্কন\",\"10. দিক নির্ণয় (Direction Sense) ও দূরত্বের হিসাব\",\"11. বসার বিন্যাস (Seating Arrangement) ও অবস্থান নির্ণয়\",\"12. র‍্যাঙ্কিং, অর্ডারিং ও তুলনামূলক উচ্চতা/বয়স নির্ণয়\",\"13. গাণিতিক যুক্তি ও ধাঁধা (Mathematical Puzzles)\",\"14. ঘড়ি ও ক্যালেন্ডার সংক্রান্ত যৌক্তিক সমস্যা\",\"15. ভেন ডায়াগ্রাম (Venn Diagram) ও সেটের যৌক্তিক প্রয়োগ\",\"16. চিত্রভিত্তিক যুক্তি (Abstract Reasoning): চিত্র পূর্ণকরণ ও প্যাটার্ন\",\"17. আয়নায় প্রতিফলন (Mirror Image) ও পানিতে প্রতিফলন (Water Image)\",\"18. ঘনক (Dice) ও ত্রিমাত্রিক বস্তুর তল গণনা\",\"19. চিত্র গণনা: ত্রিভুজ, চতুর্ভুজ ও বৃত্তের সংখ্যা নির্ণয়\",\"20. কাগজ ভাঁজ ও কাটা (Paper Folding & Cutting)\",\"21. যান্ত্রিক দক্ষতা (Mechanical Reasoning): লিভার, গিয়ার ও পুলি\",\"22. স্থানাঙ্ক সম্পর্ক ও স্থানিক সচেতনতা (Spatial Ability)\",\"23. উপাত্তের পর্যাপ্ততা (Data Sufficiency) ও যৌক্তিক সিদ্ধান্ত গ্রহণ\",\"24. স্টেটমেন্ট, আর্গুমেন্ট ও সিদ্ধান্ত (Conclusion) বিশ্লেষণ\",\"25. এনালিটিক্যাল পাজল ও ক্রিটিক্যাল থিংকিং\",\"26. ঘড়ির কাঁটার মধ্যবর্তী কোণ ও সময়ের পার্থক্য\",\"27. শব্দ ও বাক্যের এনালজি (Analogy)\",\"28. ম্যাট্রিক্স ও গ্রিড ভিত্তিক লুপ্ত সংখ্যা নির্ণয়\",\"29. দ্রুত সিদ্ধান্ত গ্রহণ (Decision Making) ও নৈতিক বিচার\",\"30. ভাষাগত দক্ষতা ও অনুচ্ছেদ ভিত্তিক আইকিউ\",\"31. জ্যামিতিক চিত্র বিশ্লেষণ ও যৌক্তিক বিন্যাস\",\"32. সংখ্যাতত্ত্বের মানসিক প্রয়োগ (Mental Arithmetic)\",\"33. ডিকোডিং ও সংকেত বিশ্লেষণ\",\"34. আইকিউ শর্টকাট টেকনিক ও লজিক অ্যাপ্লাই করার উপায়\",\"35. পূর্ববর্তী বিসিএস ও পিএসসি পরীক্ষার আইকিউ প্রশ্ন বিশ্লেষণ\",\"36. সাম্প্রতিক মানসিক দক্ষতা ও আইকিউ প্রশ্ন ট্রেন্ড\"]'),
(17, 'Morality, values & Good Governance', 'নৈতিকতা, মূল্যবোধ ও সুশাসন', 'noitikota, mullobodh o sushason', '', 4, 10, NULL, NULL, 'morality-values-good-governance', 1, '[\"1. নৈতিকতা, মূল্যবোধ ও সুশাসনের মৌলিক ধারণা ও আন্তঃসম্পর্ক\",\"2. নৈতিকতার উৎস: পরিবার, সমাজ, ধর্ম ও রাষ্ট্র\",\"3. মূল্যবোধের সংজ্ঞা, প্রকারভেদ ও বৈশিষ্ট্য\",\"4. মূল্যবোধের শিক্ষা: সহনশীলতা, সহমর্মিতা ও শ্রমের মর্যাদা\",\"5. সামাজিক মূল্যবোধের অবক্ষয়: কারণ ও প্রতিকার\",\"6. সুশাসন (Good Governance): ধারণা, বিবর্তন ও সংজ্ঞা\",\"7. বিশ্বব্যাংক ও ইউএনডিপি (UNDP) প্রদত্ত সুশাসনের বৈশিষ্ট্য\",\"8. সুশাসনের মূল স্তম্ভ: স্বচ্ছতা (Transparency) ও জবাবদিহিতা\",\"9. আইনের শাসন (Rule of Law) ও বিচার বিভাগের স্বাধীনতা\",\"10. অংশগ্রহণমূলক শাসন ব্যবস্থা ও নারীর ক্ষমতায়ন\",\"11. প্রশাসনিক নৈতিকতা ও সরকারি কর্মচারীদের আচরণবিধি\",\"12. দুর্নীতি: ধারণা, কারণ ও প্রতিরোধে আইনি কাঠামো\",\"13. বাংলাদেশে দুর্নীতি দমন কমিশন (দুদক) ও এর কার্যাবলি\",\"14. জাতীয় শুদ্ধাচার কৌশল (National Integrity Strategy - NIS)\",\"15. তথ্য অধিকার (RTI) ও সুশাসনে এর ভূমিকা\",\"16. সিটিজেন চার্টার (Citizen Charter) ও সেবা প্রদান প্রতিশ্রুতি\",\"17. ই-গভর্ন্যান্স ও ডিজিটাল সুশাসন: চ্যালেঞ্জ ও সম্ভাবনা\",\"18. গণতন্ত্র, নির্বাচন ও সুশাসনের পারস্পরিক সম্পর্ক\",\"19. রাজনৈতিক সংস্কৃতি, নেতৃত্ব ও নৈতিক নেতৃত্ব (Ethical Leadership)\",\"20. মানবাধিকার (Human Rights) ও মৌলিক অধিকারের সুরক্ষা\",\"21. ন্যায়বিচার (Justice) ও সামাজিক ইনসাফ (Social Equity)\",\"22. টেকসই উন্নয়ন লক্ষ্যমাত্রা (SDG-16) ও শান্তি-সুশাসন\",\"23. নাগরিকের দায়িত্ব, কর্তব্য ও দেশপ্রেম\",\"24. নৈতিক চিন্তাবিদ ও দার্শনিকদের দৃষ্টিভঙ্গি (সক্রেটিস, প্লেটো, অ্যারিস্টটল)\",\"25. জন রলসের ন্যায়বিচার তত্ত্ব ও ইউটিলিটারিয়ানিজম (উপযোগবাদ)\",\"26. সিভিল সার্ভিসের নৈতিকতা ও জনসেবার মানসিকতা\",\"27. কর্পোরেট সোশ্যাল রেসপন্সিবিলিটি (CSR) ও ব্যবসায়িক নৈতিকতা\",\"28. সরকারি নীতি নির্ধারণে নৈতিকতার প্রভাব\",\"29. আন্তর্জাতিক সুশাসন সূচক ও বাংলাদেশের অবস্থান\",\"30. সাম্প্রতিক সুশাসন, নৈতিকতা ও মূল্যবোধ বিষয়ক ঘটনাপ্রবাহ\"]'),
(18, '1st Paper', '১ম পত্র', 'prothom potro', '', 3, 2024, NULL, NULL, '1st-paper', 1, '[\"1. গণপ্রজাতন্ত্রী বাংলাদেশের সংবিধান (সংশ্লিষ্ট অংশ)\", \"2. বাংলাদেশ সার্ভিস রুলস (BSR - Part 1 & 2)\", \"3. সরকারি কর্মচারী (আচরণ) বিধিমালা, ১৯৭৯\", \"4. সরকারি কর্মচারী (শৃঙ্খলা ও আপিল) বিধিমালা, ২০১৮\", \"5. সরকারি চাকরি আইন, ২০১৮\", \"6. দ্য পাবলিক ডিমান্ডস রিকভারি অ্যাক্ট (PDR Act, 1913)\", \"7. দুর্নীতি প্রতিরোধ ও দমন আইনসমূহ\", \"8. দ্য রিজিডেন্সিয়াল একমোডেশন রুলস\", \"9. সরকারি অফিস ব্যবস্থাপনা ও নথিকরণ বিধিমালা\", \"10. তথ্য অধিকার আইন ও জাতীয় শুদ্ধাচার কৌশল (NIS)\"]'),
(19, '2nd Paper', '২য় পত্র', 'ditio potro', '', 3, 2024, NULL, NULL, '2nd-paper', 1, '[\"1. জেনারেল ফিন্যান্সিয়াল রুলস (GFR)\", \"2. ট্রেজারি রুলস (Treasury Rules) ও সাব-ট্রেজারি রুলস\", \"3. ফান্ডামেন্টাল রুলস (FR) ও সাপ্লিমেন্টারি রুলস (SR)\", \"4. বাংলাদেশ সার্ভিস রুলস (আর্থিক অংশ - BSR Part-1)\", \"5. সাধারণ ভবিষ্যৎ তহবিল (GPF) ও পেনশন বিধিমালা\", \"6. ভ্রমণ ভাতা (TA) ও দৈনিক ভাতা (DA) বিধিমালা\", \"7. সরকারি ক্রয়ের ধারণা ও পিপিএ (PPA-2006) / পিপিআর (PPR-2008)\", \"8. বাজেট প্রণয়ন, বরাদ্দ ও উপযোজন (Appropriation)\", \"9. সরকারি অডিট (Audit) ও অডিট আপত্তির জবাব প্রদান\", \"10. ভ্যাট (VAT), আয়কর (Income Tax) ও উৎসে কর কর্তন বিধি\"]'),
(20, '3rd Paper', '৩য় পত্র', 'tritiyo potro', '', 3, 2024, NULL, NULL, '3rd-paper', 1, '[\"1. মাধ্যমিক ও উচ্চ শিক্ষা অধিদপ্তর (DSHE) এর সাংগঠনিক কাঠামো ও কার্যাবলি\", \"2. বেসরকারি শিক্ষা প্রতিষ্ঠান (MPO) নীতিমালা ও জনবল কাঠামো\", \"3. শিক্ষা মন্ত্রণালয় ও সংশ্লিষ্ট পরিদপ্তরের প্রশাসনিক কার্যাবলি\", \"4. জাতীয় শিক্ষানীতি (২০১০) ও এর বাস্তবায়ন\", \"5. শিক্ষা প্রতিষ্ঠানের গভর্নিং বডি ও ম্যানেজিং কমিটি বিধিমালা\", \"6. শিক্ষা আইন ও বিধিমালা (বোর্ড ও বিশ্ববিদ্যালয়ের সংশ্লিষ্ট অংশ)\", \"7. শিক্ষক প্রশিক্ষণ ও পেশাগত উন্নয়ন (NAEM, NCTB, BIISS)\", \"8. শিক্ষা প্রতিষ্ঠানের আর্থিক ব্যবস্থাপনা ও অডিট (শিক্ষা ক্যাডার বিশেষ)\", \"9. পরীক্ষা পরিচালনা ও মূল্যায়ন পদ্ধতি (বোর্ড ও এনসিটিবি)\", \"10. সাম্প্রতিক শিক্ষা সংস্কার ও ডিজিটাল রূপান্তর (Smart Education)\"]'),
(21, 'Higher Math 1st', 'উচ্চতর গনিত ১ম পত্র', 'ucchotor gonit 1st', '', 2, 2025, NULL, NULL, 'higher-math-1st', 1, '[\"1. ম্যাট্রিক্স ও নির্ণায়ক\", \"2. ভেক্টর\", \"3. সরলরেখা\", \"4. বৃত্ত\", \"5. বিন্যাস ও সমাবেশ\", \"6. ত্রিকোণমিতিক অনুপাত\", \"7. সংযুক্ত কোণের ত্রিকোণমিতিক অনুপাত\", \"8. ফাংশন ও ফাংশনের লেখচিত্র\", \"9. অন্তরীকরণ\", \"10. যোগজীকরণ\"]'),
(22, 'Higher Math 2nd', 'উচ্চতর গনিত ২য় পত্র', 'ucchotor gonit 2nd', '', 2, 2025, NULL, NULL, 'higher-math-2nd', 1, '[\"1. বাস্তব সংখ্যা ও অসমতা\", \"2. যোগাশ্রয়ী প্রোগ্রাম\", \"3. জটিল সংখ্যা\", \"4. বহুপদী ও বহুপদী সমীকরণ\", \"5. দ্বিপদী বিস্তৃতি\", \"6. কণিক\", \"7. বিপরীত ত্রিকোণমিতিক ফাংশন ও ত্রিকোণমিতিক সমীকরণ\", \"8. স্থিতিবিদ্যা\", \"9. সমতলে বস্তুকণার গতি\", \"10. বিস্তার পরিমাপ ও সম্ভাবনা\"]'),
(23, 'Chemistry 1st', 'রসায়ন বিজ্ঞান ১ম', 'rosayon biggan 1st', '', 2, 0, NULL, NULL, 'chemistry-1st', 1, '[\"১. ল্যাবরেটরির নিরাপদ ব্যবহার\", \"২. গুণগত রসায়ন\", \"৩. মৌলের পর্যায়বৃত্ত ধর্ম ও রাসায়নিক বন্ধন\", \"৪. রাসায়নিক পরিবর্তন\", \"৫. কর্মমুখী রসায়ন\"]'),
(24, 'Chemistry 2nd', 'রসায়ন বিজ্ঞান ২য়', 'rosayon biggan 2nd', '', 2, 0, NULL, NULL, 'chemistry-2nd', 1, '[\"১. পরিবেশ রসায়ন\", \"২. জৈব রসায়ন\", \"৩. পরিমাণগত রসায়ন\", \"৪. তড়িৎ রসায়ন\", \"৫. অর্থনৈতিক রসায়ন\"]');
INSERT INTO `syllabuses` (`id`, `subject_id`, `chapter`, `title`, `topics`) VALUES
(1, 5, 1, 'তথ্য ও যোগাযোগ প্রযুক্তি: বিশ্ব ও বাংলাদেশ প্রেক্ষিত', '[\"বিশ্বগ্রাম (Global Village) ও এর উপাদানসমূহ\", \"ভার্চুয়াল রিয়ালিটি (Virtual Reality) ও এর ব্যবহার\", \"কৃত্রিম বুদ্ধিমত্তা (Artificial Intelligence)\", \"রোবোটিক্স (Robotics) ও এর গঠন ও ব্যবহার\", \"ক্রায়োসার্জারি (Cryosurgery) ও এর প্রয়োগ\", \"মহাকাশ অভিযান (Space Exploration) ও আইসিটি\", \"বায়োমেট্রিক্স (Biometrics) প্রযুক্তির প্রকারভেদ ও ব্যবহার\", \"বায়োইনফরমেটিক্স (Bioinformatics) ও এর গুরুত্ব\", \"জেনেটিক ইঞ্জিনিয়ারিং (Genetic Engineering) ও এর প্রয়োগ\", \"ন্যানোটেকনোলজি (Nanotechnology) ও এর প্রভাব\", \"দৈনন্দিন জীবনে আইসিটি: শিক্ষা, চিকিৎসা, কৃষি ও কর্মসংস্থান\", \"সাইবার অপরাধ, ডিজিটাল নিরাপত্তা, নৈতিকতা ও সামাজিক প্রভাব\"]'),
(2, 5, 2, 'কমিউনিকেশন সিস্টেমস ও নেটওয়ার্কিং', '[\"ডেটা কমিউনিকেশন ও এর উপাদানসমূহ\", \"ডেটা ট্রান্সমিশন মেথড ও ট্রান্সমিশন মোডসমূহ\", \"ডেটা ট্রান্সমিশন মিডিয়া (তার ও তারবিহীন মাধ্যমসমূহ)\", \"মোবাইল কমিউনিকেশন (1G, 2G, 3G, 4G ও 5G বিবর্তন)\", \"ওয়ারলেস কমিউনিকেশন প্রযুক্তি (ব্লুটুথ, ওয়াই-ফাই, ওয়াইম্যাক্স)\", \"কম্পিউটার নেটওয়ার্ক টপোলজি (বাস, স্টার, রিং, ট্রি, মেশ, হাইব্রিড)\", \"নেটওয়ার্ক হার্ডওয়্যার (রাউটার, সুইচ, হাব, গেটওয়ে, মডেম, সার্ভার)\"]'),
(3, 5, 3, 'সংখ্যা পদ্ধতি ও ডিজিটাল ডিভাইস', '[\"সংখ্যা পদ্ধতির ধারণা (দশমিক, বাইনারি, অক্টাল ও হেক্সাডেসিমেল)\", \"বিভিন্ন সংখ্যা পদ্ধতির মধ্যে পারস্পরিক রূপান্তর\", \"বাইনারি যোগ, বিয়োগ ও গাণিতিক সমস্যা সমাধান\", \"চিহ্নযুক্ত সংখ্যা ও ২-এর পরিপূরক (2\'s Complement) পদ্ধতি\", \"কোড (BCD, ASCII, EBCDIC ও ইউনিকোড)\", \"বুলিয়ান অ্যালজেব্রা ও মৌলিক উপপাদ্যসমূহ\", \"লজিক গেট (মৌলিক গেট, সার্বজনীন গেট, বিশেষ গেট)\", \"কম্বিনেশনাল সার্কিট (অ্যাডার, এনকোডার, ডিকোডার, মাল্টিপ্লেক্সার)\", \"সিকোয়েন্সিয়াল সার্কিট (ল্যাচ, ফ্লিপ-ফ্লপ, রেজিস্টার ও কাউন্টার)\"]'),
(4, 5, 4, 'ওয়েব ডিজাইন পরিচিতি ও HTML', '[\"ওয়েব ডিজাইনের ধারণা ও ওয়েবসাইট কাঠামো\", \"HTML পরিচিতি ও এর বৈশিষ্ট্য\", \"HTML ট্যাগ, এলিমেন্ট ও এর গঠনপ্রণালী\", \"টেক্সট ফরম্যাটিং ও হেডিংয়ের ব্যবহার\", \"HTML টেবিল ও লিস্ট তৈরি করার নিয়ম\", \"হাইপারলিংক ও ইমেজ যুক্ত করার পদ্ধতি\", \"ওয়েব ফর্ম তৈরি ও এর ব্যবহার\", \"CSS (Cascading Style Sheets) এর প্রাথমিক ধারণা\", \"ওয়েব পাবলিশিং ও ওয়েব হোস্টিং প্রক্রিয়া\"]'),
(5, 5, 5, 'প্রোগ্রামিং ভাষা', '[\"অ্যালগরিদম ও ফ্লোচার্ট তৈরির নিয়মাবলী\", \"প্রোগ্রামিং ভাষার ইতিহাস ও পর্যায়ক্রমিক উন্নয়ন\", \"C প্রোগ্রামের গঠন ও এর মৌলিক উপাদানসমূহ\", \"ডেটা টাইপ, ধ্রুবক (Constants) ও ভেরিয়েবল (Variables)\", \"অপারেটর ও এক্সপ্রেশন (Operators & Expressions)\", \"ইনপুট ও আউটপুট ফাংশনের ব্যবহার\", \"কন্ট্রোল স্টেটমেন্ট (If, If-Else, Switch)\", \"লুপ বা পুনরাবৃত্তি (For, While, Do-While Loop)\", \"অ্যারে (Array) ও ইউজার ডিফাইনড ফাংশন (Functions)\"]'),
(6, 5, 6, 'ডেটাবেস ম্যানেজমেন্ট সিস্টেম', '[\"ডেটাবেস ম্যানেজমেন্ট সিস্টেমের ধারণা ও সুবিধা\", \"ডেটা মডেল ও এনটিটি-রিলেশনশিপ মডেল (ER Model)\", \"ডেটাবেস কি (Primary Key, Foreign Key, Candidate Key)\", \"SQL (Structured Query Language) এর পরিচিতি ও ব্যবহার\", \"DDL (Data Definition Language) কমান্ডসমূহ\", \"DML (Data Manipulation Language) কমান্ডসমূহ\", \"ডেটাবেস নরমালাইজেশন (Normalization) এর ধারণা\"]'),
(7, 6, 1, 'ভৌতজগৎ ও পরিমাপ', '[\"ভৌতরাশির পরিমাপ ও একক\", \"ভৌতরাশির মাত্রার সমীকরণ\", \"পরিমাপের ত্রুটি ও নির্ভুলতা\", \"পরিমাপক যন্ত্রের ব্যবহার (স্লাইড ক্যালিপার্স, স্ক্রু-গজ)\"]'),
(8, 6, 2, 'ভেক্টর', '[\"ভেক্টরের প্রকারভেদ\", \"ভেক্টর যোগ ও বিয়োগের নিয়ম\", \"ভেক্টরের বিভাজন ও উপাংশ\", \"ডট গুণন ও ক্রস গুণন\", \"ভেক্টর ক্যালকুলাস (গ্রেডিয়েন্ট, ডাইভারজেন্স, কার্ল)\"]'),
(9, 6, 3, 'গতিবিদ্যা', '[\"গতির সমীকরণ ও লেখচিত্র\", \"প্রাসের গতি (Projectile Motion)\", \"গতির সূত্রাবলি ও প্রয়োগ\"]'),
(10, 6, 4, 'নিউটনীয় বলবিদ্যা', '[\"নিউটনের গতির সূত্রাবলি\", \"জড়তার ভ্রামক (Moment of Inertia)\", \"কৌণিক ভরবেগ ও টর্ক\", \"সংঘর্ষের প্রকারভেদ (স্থিতিস্থাপক ও অস্থিতিস্থাপক)\"]'),
(11, 6, 5, 'কাজ, শক্তি ও ক্ষমতা', '[\"কাজ ও শক্তির রূপান্তর\", \"বিভব শক্তি ও গতিশক্তি\", \"ক্ষমতা ও কর্মদক্ষতা\", \"শক্তির নিত্যতা সূত্র\"]'),
(12, 6, 6, 'মহাকর্ষ ও অভিকর্ষ', '[\"নিউটনের মহাকর্ষ সূত্র\", \"অভিকর্ষজ ত্বরণ ও এর পরিবর্তন\", \"মহাকর্ষীয় বিভব ও প্রাবল্য\", \"কৃত্রিম উপগ্রহ ও মুক্তিবেগ\"]'),
(13, 6, 7, 'পদার্থের গাঠনিক ধর্ম', '[\"স্থিতিস্থাপকতা ও হুকের সূত্র\", \"ইয়ংয়ের গুণাঙ্ক\", \"সান্দ্রতা ও স্টোকসের সূত্র\", \"পৃষ্ঠটান ও কৈশিকতা\"]'),
(14, 6, 8, 'পর্যায়বৃত্ত গতি', '[\"সরল ছন্দিত স্পন্দন (SHM)\", \"সরল দোলক ও এর পর্যায়কাল\", \"দোলনের শক্তি ও লেখচিত্র\"]'),
(15, 6, 9, 'তরঙ্গ', '[\"তরঙ্গের বৈশিষ্ট্য ও সমীকরণ\", \"তরঙ্গের উপরিপাতন ও ব্যতিচার\", \"অ্যানোডের কম্পন ও স্থির তরঙ্গ\", \"ডপলার প্রভাব (Doppler Effect)\"]'),
(16, 6, 10, 'আদর্শ গ্যাস ও গ্যাসের গতিতত্ত্ব', '[\"গ্যাসের গতিতত্ত্বের স্বীকার্য\", \"গ্যাসের সূত্রাবলি (বয়েল, চার্লস, চাপের সূত্র)\", \"গ্যাসের গড়ের বর্গমূলীয় বেগ\", \"গ্যাসের অণুর স্বাধীনতার মাত্রা\"]'),
(17, 7, 1, 'তাপগতিবিদ্যা', '[\"তাপগতিবিদ্যার প্রথম ও দ্বিতীয় সূত্র\", \"এন্ট্রপি (Entropy) ও তাপীয় ইঞ্জিন\", \"কার্নো চক্র ও দক্ষতা (Efficiency)\", \"তাপগতিবিদ্যার প্রক্রিয়া (সমোষ্ণ, রুদ্ধতাপীয়, সমচাপ, সমায়তন)\"]'),
(18, 7, 2, 'স্থির তড়িৎ', '[\"কুলম্বের সূত্র ও তড়িৎ ক্ষেত্র\", \"তড়িৎ বিভব ও প্রাবল্য\", \"গাউসের সূত্র ও এর প্রয়োগ\", \"ধারক ও ধারকত্ব (Capacitor)\"]'),
(19, 7, 3, 'চল তড়িৎ', '[\"তড়িৎ প্রবাহ, বিভব ও রোধ (ওহমের সূত্র)\", \"কারশফের সূত্র ও হুইটস্টোন ব্রিজ\", \"তড়িৎ ক্ষমতা ও ফিউজ\", \"পটেনশিওমিটার ও মিটার ব্রিজ\"]'),
(20, 7, 4, 'তড়িৎ প্রবাহের চৌম্বক ক্রিয়া ও চুম্বকত্ব', '[\"বায়ো-সাভার্ট সূত্র ও অ্যাম্পিয়ারের সূত্র\", \"লরেন্জ বল ও চৌম্বক ক্ষেত্রে আধানের গতি\", \"হলের প্রভাব (Hall Effect)\", \"ম্যাগনেটিক ডাইপোল ও ভূ-চুম্বকত্ব\"]'),
(21, 7, 5, 'তড়িৎ চৌম্বক আবেশ ও পরিবর্তী প্রবাহ', '[\"ফ্যারাডের তড়িৎ চৌম্বক আবেশ সূত্র\", \"লেন্জের সূত্র ও স্বকীয় আবেশ\", \"ট্রান্সফরমার (Transformer) ও এর কার্যপদ্ধতি\", \"AC সার্কিট ও রেজোন্যান্স\"]'),
(22, 7, 6, 'জ্যামিতিক আলোকবিজ্ঞান', '[\"প্রতিসরণ ও পূর্ণ অভ্যন্তরীণ প্রতিফলন\", \"লেন্স ও দর্পণের সমীকরণ\", \"প্রিজম ও বিচ্যুতি\", \"মানুষের চোখের ত্রুটি ও প্রতিকার\"]'),
(23, 7, 7, 'ভৌত আলোকবিজ্ঞান', '[\"আলোর ব্যতিচার (Interference) ও ইয়ংয়ের দ্বি-চির পরীক্ষা\", \"অপবর্তন (Diffraction) ও সমবর্তন (Polarization)\", \"হাইগেন্সের নীতি ও আলোর প্রকৃতি\"]'),
(24, 7, 8, 'আধুনিক পদার্থবিজ্ঞানের সূচনা', '[\"আপেক্ষিকতার বিশেষ তত্ত্ব\", \"কাল দীর্ঘায়ন (Time Dilation) ও দৈর্ঘ্যের সংকোচন\", \"ভর-শক্তি সমতুল্যতা ($E=mc^2$)\", \"ফটোন ও আলোক তড়িৎ ক্রিয়া\"]'),
(25, 7, 9, 'পরমাণুর মডেল ও নিউক্লিয়ার পদার্থবিজ্ঞান', '[\"বোর মডেল ও হাইড্রোজেন বর্ণালি\", \"নিউক্লিয়াস, তেজস্ক্রিয়তা ও অর্ধায়ু\", \"নিউক্লিয়ার ফিউশন ও ফিশন বিক্রিয়া\", \"আইসোটোপ ও এর ব্যবহার\"]'),
